/* MSG-01 · Lista de Hilos — estilos de la pantalla */

.page {
  min-width: 0;
  /* El fondo Cold White lo aporta el área de contenido del shell; esta
     pantalla no pinta su propio fondo. */
}

.eyebrow {
  margin: 0 0 4px;
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-hint);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-eyebrow);
  color: var(--bw-steel-mist);
