  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-deep-steel);
}

.pageSub {
  margin: 0 0 16px;
  max-width: 560px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-text-secondary);
}

.e2eeBar {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 14px;
  padding: 6px 10px;
  font-family: var(--bw-font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--bw-success-dark);
  background: var(--bw-badge-success-bg);
  border: 1px solid var(--bw-badge-success-border);
  border-radius: var(--bw-radius);
}

.e2eeBar i {
  font-size: 12px;
}

.actionsBar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px 12px;
  margin-bottom: 14px;
}

.searchForm {
  position: relative;
  flex: 1 1 220px;
  max-width: 300px;
}

.searchForm > i {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--bw-input-placeholder);
  font-size: 15px;
  pointer-events: none;
}

.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 32px;
  font-family: inherit;
  font-size: var(--bw-size-input);
  color: var(--bw-input-text);
  background: none;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.searchInput:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.srOnly {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.newContact {
  display: flex;
  align-items: center;
  gap: 8px;
}

.primaryButton {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 18px;
  font-family: inherit;
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  background: var(--bw-calibration-blue);
  /* No hay token de blanco puro; se usa el neutro de superficie más claro. */
  color: var(--bw-cold-white);
  border: 0;
  border-radius: var(--bw-radius);
  cursor: pointer;
  transition: opacity 0.12s ease;
}

.primaryButton:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.primaryButton i {
  font-size: 15px;
}

.outOfScope {
  max-width: 220px;
  font-size: 11px;
  line-height: 1.4;
  color: var(--bw-input-placeholder);
}

.resultInfo {
  margin-left: auto;
  font-size: 12px;
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

.errorBox {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-bottom: 14px;
  padding: 10px 12px;
  font-size: 13px;
  line-height: 1.5;
  color: var(--bw-sensitive-text);
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: var(--bw-radius);
}

.errorBox i {
  margin-top: 1px;
  font-size: 15px;
}

.loadingBox {
  padding: 28px 16px;
  text-align: center;
  font-size: 13px;
  color: var(--bw-text-secondary);
  border: 1px solid var(--bw-line-steel);
  border-radius: var(--bw-radius);
}

.loadingHint {
  margin: 0 0 10px;
  font-size: 12px;
  color: var(--bw-text-secondary);
}

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

.pageArrow,
.pageNumber {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  font-family: inherit;
  font-size: 12px;
  background: none;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  cursor: pointer;
  transition: border-color 0.12s ease, color 0.12s ease;
}

.pageArrow:hover:not(:disabled),
.pageNumber:hover:not(:disabled) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageArrow:disabled,
.pageNumber:disabled {
  color: var(--bw-input-placeholder);
  cursor: not-allowed;
}

.pageNumberActive {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  color: var(--bw-cold-white);
  cursor: default;
}

.pageNumberActive:hover:not(:disabled) {
  border-color: var(--bw-deep-steel);
  color: var(--bw-cold-white);
}

.pageEllipsis {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 24px;
  height: 30px;
  color: var(--bw-input-placeholder);
}

