import { useEffect, useState, type FormEvent } from 'react';
import type { MemberProfile } from '../../lib/session';
import { fetchThreadPage, pageCount, type ThreadPage } from '../../lib/threads';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

/**
 * Pantalla MSG-01 · Lista de Hilos.
 *
 * Es la pantalla, no un componente de presentación: recibe la sesión, llama a
 * `fetchThreadPage` con `profile.orgId` y posee el estado de búsqueda y de página.
 *
 * `onOpenThread` es parte de la firma pública (F-118) pero no se usa: MSG-02 no
 * forma parte de estas ocho pantallas, y abrir un hilo no lleva a ningún sitio.
 * La prop se declara en el tipo para que `App.tsx` compile, y aquí se ignora.
 */

/** Extrae el texto real de un error de PostgREST o de un Error. */
function describeError(error: unknown): string {
  if (error instanceof Error) {
    return error.message.length > 0 ? error.message : String(error);
  }
  if (typeof error === 'object' && error !== null) {
    const record = error as Record<string, unknown>;
    const fragments = [
      typeof record.code === 'string' ? record.code : '',
      typeof record.message === 'string' ? record.message : '',
    ].filter((part) => part.length > 0);
    if (fragments.length > 0) return fragments.join(' · ');
  }
  const text = String(error);
  return text !== '' && text !== '[object Object]' ? text : 'Error desconocido';
}

type PageItem = number | '…';

function pageItems(current: number, total: number): PageItem[] {
  if (total <= 7) {
    return Array.from({ length: total }, (_, index) => index + 1);
  }
  const start = Math.max(1, Math.min(current - 2, total - 4));
  const end = Math.min(total, start + 4);
  const items: PageItem[] = [];
  if (start > 1) items.push(1, '…');
  for (let p = start; p <= end; p += 1) items.push(p);
  if (end < total) items.push('…', total);
  return items;
}

export function Messages({
  profile,
  now = new Date(),
}: {
  profile: MemberProfile;
  now?: Date | undefined;
  onOpenThread?: (threadId: string) => void;
}) {
  const [searchText, setSearchText] = useState('');
  const [query, setQuery] = useState('');
  const [page, setPage] = useState(1);
  const [result, setResult] = useState<ThreadPage | null>(null);
  const [error, setError] = useState<unknown>(null);
  const [busy, setBusy] = useState(true);

  useEffect(() => {
    let alive = true;
    setBusy(true);
    setError(null);

    fetchThreadPage({ orgId: profile.orgId, search: query, page })
      .then((next) => {
        if (alive) setResult(next);
      })
      .catch((reason: unknown) => {
        if (alive) {
          setError(reason);
          setResult(null);
        }
      })
      .finally(() => {
        if (alive) setBusy(false);
      });

    return () => {
      alive = false;
    };
  }, [profile.orgId, query, page]);

  const handleSearchSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setQuery(searchText.trim());
    setPage(1);
  };

  const totalPages = result ? pageCount(result.total) : 1;

  return (
    <div className={styles.page}>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.pageTitle}>Hilos</h1>
      <p className={styles.pageSub}>
        Tus conversaciones con otros distribuidores. Todo el contenido está
        cifrado de extremo a extremo.
      </p>

      <div className={styles.e2eeBar}>
        <i className="ti ti-lock" aria-hidden="true" />
        E2EE activo · claves en memoria de sesión · contenido descifrado
        localmente
      </div>

      <div className={styles.actionsBar}>
        <form className={styles.searchForm} onSubmit={handleSearchSubmit}>
          <i className="ti ti-search" aria-hidden="true" />
          <label className={styles.srOnly} htmlFor="threadSearchInput">
            Buscar por nombre de organización
          </label>
          <input
            id="threadSearchInput"
            className={styles.searchInput}
            type="text"
            placeholder="Buscar por nombre de organización..."
            value={searchText}
            onChange={(event) => setSearchText(event.target.value)}
          />
        </form>

        <div className={styles.newContact}>
          <button type="button" className={styles.primaryButton} disabled>
            <i className="ti ti-address-book" aria-hidden="true" />
            Nuevo contacto
          </button>
          <span className={styles.outOfScope} data-testid="directorio-scope">
            El Directorio queda fuera del MVP
          </span>
        </div>

        {result !== null && result.total > 0 && (
          <span className={styles.resultInfo} data-testid="pag-info">
            {result.total.toLocaleString('es-ES')} hilos · Página{' '}
            {page.toLocaleString('es-ES')} de{' '}
            {pageCount(result.total).toLocaleString('es-ES')}
          </span>
        )}
      </div>

      {error !== null && (
        <div className={styles.errorBox} role="alert">
          <i className="ti ti-alert-triangle" aria-hidden="true" />
          <span>No se pudieron cargar los hilos. {describeError(error)}</span>
        </div>
      )}

      {busy && result === null && error === null && (
        <div className={styles.loadingBox} role="status">
          Cargando hilos…
        </div>
      )}

      {busy && result !== null && error === null && (
        <p className={styles.loadingHint} role="status">
          Actualizando lista…
        </p>
      )}

      {result !== null && error === null && (
        <ThreadList threads={result.threads} now={now} onOpen={() => {}} />
      )}

      {result !== null && result.total > 0 && (
        <div className={styles.pagination}>
          <button
            type="button"
            className={styles.pageArrow}
            aria-label="Página anterior"
            disabled={page <= 1 || busy}
            onClick={() => setPage(Math.max(1, page - 1))}
          >
            ‹
          </button>
          {pageItems(page, totalPages).map((item, index) =>
            item === '…' ? (
              <span
                key={`page-gap-${index}`}
                className={styles.pageEllipsis}
                aria-hidden="true"
              >
                …
              </span>
            ) : (
              <button
                key={item}
                type="button"
                className={
                  item === page
                    ? `${styles.pageNumber} ${styles.pageNumberActive}`
                    : styles.pageNumber
                }
                aria-current={item === page ? 'page' : undefined}
                disabled={busy}
                onClick={() => setPage(item)}
              >
                {item.toLocaleString('es-ES')}
              </button>
            ),
          )}
          <button
            type="button"
            className={styles.pageArrow}
            aria-label="Página siguiente"
            disabled={page >= totalPages || busy}
            onClick={() => setPage(Math.min(totalPages, page + 1))}
          >
            ›
          </button>
        </div>
      )}
    </div>
  );
}

