/* MSG-01 · Lista de hilos — estilos presentacionales */

.threadList {
  list-style: none;
  margin: 0;
  padding: 0;
  border: 1px solid var(--bw-line-steel);
  /* El mock usa 8px; el token del sistema de diseño es 3px. */
  border-radius: var(--bw-radius);
  overflow: hidden;
  /* El blanco puro de la tarjeta del HTML aprobado no tiene token en el sistema;
     se deja sin fondo para heredar la superficie clara del contenedor. */
}

.threadItem {
  transition: background 0.12s ease;
}

.threadItem + .threadItem {
  border-top: 1px solid var(--bw-divider-mist);
}

.threadItem:hover {
  background: var(--bw-row-hover-tint);
}

.threadRow {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 5px 10px;
  width: 100%;
  padding: 14px 18px;
  border: 0;
  background: none;
  text-align: left;
  cursor: pointer;
  color: inherit;
  font-family: inherit;
}

.threadRow:focus-visible {
  outline: 2px solid var(--bw-calibration-blue);
  outline-offset: -2px;
}

.threadTop {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.threadOrg {
  display: block;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-deep-steel);
}

.countryBadge {
  flex-shrink: 0;
  font-family: var(--bw-font-mono);
  font-size: 10px;
  padding: 1px 6px;
  border-radius: 2px;
  background: var(--bw-cold-white);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-line-steel);
  white-space: nowrap;
}

.threadTsRow {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
}

.threadTs {
  font-family: var(--bw-font-mono);
  font-size: 10px;
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

.threadBot {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.threadPreview {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
  color: var(--bw-text-secondary);
}

.stateBadge {
  flex-shrink: 0;
  font-family: var(--bw-font-mono);
  font-size: 9px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 2px 7px;
  border-radius: 2px;
  white-space: nowrap;
}

.badgeAbierto {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-badge-neutral-border);
}

.badgeConsulta {
  background: var(--bw-chip-active-bg);
  color: var(--bw-calibration-blue);
  border: 1px solid var(--bw-chip-active-border);
}

.badgeOferta {
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning);
  border: 1px solid var(--bw-badge-warning-border);
}

.badgeAcuerdo {
  background: var(--bw-badge-success-bg);
  color: var(--bw-success-dark);
  border: 1px solid var(--bw-badge-success-border);
}

.badgeCerrado {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-input-placeholder);
  border: 1px solid var(--bw-badge-neutral-border-soft);
  text-decoration: line-through;
}

/* ── Estado vacío (F-128, F-141) ──────────────────────────────────────── */
/* Contenedor propio, fuera de cualquier <ul>: con cero hilos no puede quedar
   ningún rol listitem en el documento. */
.emptyState {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 32px 24px;
  text-align: center;
  border: 1px solid var(--bw-line-steel);
  border-radius: var(--bw-radius);
}

.emptyText {
  margin: 0;
  max-width: 440px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-text-secondary);
}

.emptyActionRow {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 10px 12px;
}

.emptyButton {
  display: inline-flex;
  align-items: center;
  height: 36px;
  padding: 0 18px;
  border: 0;
  border-radius: var(--bw-radius);
  background: var(--bw-calibration-blue);
  color: var(--bw-cold-white);
  font-family: inherit;
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  cursor: not-allowed;
  opacity: 0.55;
}

.outOfScope {
  font-size: 11px;
  line-height: 1.4;
  color: var(--bw-input-placeholder);
}

