import {
  previewLabel,
  relativeTime,
  stateTone,
  type StateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

/**
 * Lista de hilos de MSG-01, presentacional.
 *
 * Recibe las filas ya cargadas y las pinta en el orden que le llegan: el orden
 * viene del servidor (`last_item_at` descendente). No carga datos ni pagina.
 *
 * La fila se construye con un `<button>` DENTRO del `<li>` a propósito: el `<li>`
 * tiene que seguir siendo `listitem` (F-131), y el botón interior es el que lleva
 * el nombre accesible y el manejador de apertura.
 */

const TONE_CLASS: Record<StateTone, string | undefined> = {
  neutral: styles.badgeAbierto,
  info: styles.badgeConsulta,
  warn: styles.badgeOferta,
  success: styles.badgeAcuerdo,
  closed: styles.badgeCerrado,
};

export function ThreadList({
  threads,
  now,
  onOpen,
}: {
  threads: ThreadSummary[];
  now?: Date | undefined;
  onOpen: (id: string) => void;
}) {
  if (threads.length === 0) {
    // Estado vacío fuera de cualquier <ul>: no debe quedar ningún listitem.
    return (
      <div className={styles.emptyState}>
        <p className={styles.emptyText}>
          Todavía no tienes ninguna conversación. Usa el Directorio para contactar
          con otras organizaciones.
        </p>
        <div className={styles.emptyActionRow}>
          <button type="button" className={styles.emptyButton} disabled>
            Ir al Directorio
          </button>
          <span className={styles.outOfScope}>
            El Directorio queda fuera del MVP
          </span>
        </div>
      </div>
    );
  }

  return (
    <ul className={styles.threadList}>
      {threads.map((thread) => {
        const toneClass = TONE_CLASS[stateTone(thread.state)] ?? '';
        return (
          <li key={thread.id} className={styles.threadItem}>
            <button
              type="button"
              className={styles.threadRow}
              onClick={() => onOpen(thread.id)}
            >
              <span className={styles.threadTop}>
                <span className={styles.threadOrg}>{thread.counterpartyName}</span>
                {thread.counterpartyCountry ? (
                  <span className={styles.countryBadge}>
                    {thread.counterpartyCountry}
                  </span>
                ) : null}
              </span>
              <span className={styles.threadTsRow}>
                <time className={styles.threadTs} dateTime={thread.lastItemAt}>
                  {relativeTime(thread.lastItemAt, now)}
                </time>
              </span>
              <span className={styles.threadBot}>
                <span className={styles.threadPreview}>
                  {previewLabel(thread.lastItem)}
                </span>
                <span className={`${styles.stateBadge} ${toneClass}`}>
                  {thread.state}
                </span>
              </span>
            </button>
          </li>
        );
      })}
    </ul>
  );
}
